import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int q = in.nextInt();
        long ans = 1;
        for (int i = 0; i < q; i++) ans *= 16;
        System.out.println(ans);
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int q;
    cin >> q;
    long long ans = 1;
    for (int i = 0; i < q; i++) ans *= 16;
    cout << ans << endl;
    return 0;
}
